import de.rub.nds.tlsattacker.core.layer.impl.QuicFrameLayer;
import de.rub.nds.tlsattacker.core.quic.frame.*;
import java.io.*;
/** Round-trips every retained frame through the repaired parser/serializer pair. */
public class CodecTest {
    static byte[] vi(long value) {
        return de.rub.nds.tlsattacker.core.quic.util.VariableLengthIntegerEncoding.encodeVariableLengthInteger(value);
    }
    static byte[] cat(byte[]... parts) {
        ByteArrayOutputStream o=new ByteArrayOutputStream();
        for(byte[] p:parts) o.writeBytes(p);
        return o.toByteArray();
    }
    static void check(String name, byte[] bytes) throws Exception {
        long type = bytes[0] & 0xffL;
        QuicFrame frame = QuicFrameLayer.create(type);
        if (frame == null) throw new IllegalStateException("no frame for " + name);
        InputStream in = new ByteArrayInputStream(bytes);
        frame.getParser(in).parse(frame);
        if (in.available() != 0) throw new IllegalStateException(name + ": trailing bytes " + in.available());
        byte[] out = frame.getSerializer().serialize();
        if (!java.util.Arrays.equals(out, bytes))
            throw new IllegalStateException(name + ": " + java.util.HexFormat.of().formatHex(bytes) + " != " + java.util.HexFormat.of().formatHex(out));
        System.out.println("ok " + name + " " + java.util.HexFormat.of().formatHex(bytes));
    }
    public static void main(String[] args) throws Exception {
        check("padding", new byte[]{0});
        check("ping", new byte[]{1});
        check("ack", cat(new byte[]{2}, vi(40), vi(7), vi(0), vi(9)));
        check("ack-pairs", cat(new byte[]{2}, vi(40), vi(7), vi(2), vi(9), vi(3), vi(1)));
        check("ack-ecn", cat(new byte[]{3}, vi(40), vi(7), vi(3), vi(9), vi(3), vi(1), vi(2), vi(0), vi(1), vi(2), vi(3)));
        check("reset", cat(new byte[]{4}, vi(3_000_000_000L), vi(7), vi(4_600_000_000_000_000_000L)));
        check("stop", cat(new byte[]{5}, vi(12), vi(3)));
        check("crypto", cat(new byte[]{6}, vi(1000), vi(3), new byte[]{1,2,3}));
        check("stream-full", cat(new byte[]{0x0f}, vi(4), vi(1000), vi(2), new byte[]{9,8}));
        check("stream-off", cat(new byte[]{0x0c}, vi(4), vi(1000), new byte[]{9,8}));
        check("stream-len", cat(new byte[]{0x0a}, vi(4), vi(2), new byte[]{9,8}));
        check("stream-bare", cat(new byte[]{0x08}, vi(4), new byte[]{9,8}));
        check("stream-finished", cat(new byte[]{0x09}, vi(4), new byte[]{9,8}));
        check("stream-zero-len", cat(new byte[]{0x0e}, vi(4), vi(0), vi(0)));
        check("max-data", cat(new byte[]{0x10}, vi(1L<<40)));
        check("max-stream-data", cat(new byte[]{0x11}, vi(4), vi(1L<<40)));
        check("max-streams-bidi", cat(new byte[]{0x12}, vi(5)));
        check("max-streams-uni", cat(new byte[]{0x13}, vi(1L<<50)));
        check("data-blocked", cat(new byte[]{0x14}, vi(9)));
        check("stream-data-blocked", cat(new byte[]{0x15}, vi(4), vi(9)));
        check("streams-blocked", cat(new byte[]{0x16}, vi(9)));
        check("new-cid", cat(new byte[]{0x18}, vi(3), vi(2), new byte[]{5}, new byte[]{1,2,3,4,5}, new byte[16]));
        check("retire-cid", cat(new byte[]{0x19}, vi(2)));
        check("path-challenge", cat(new byte[]{0x1a}, new byte[]{1,2,3,4,5,6,7,8}));
        check("path-response", cat(new byte[]{0x1b}, new byte[]{1,2,3,4,5,6,7,8}));
        check("close-quic", cat(new byte[]{0x1c}, vi(1), vi(6), vi(2), new byte[]{65,66}));
        check("close-app", cat(new byte[]{0x1d}, vi(1), vi(2), new byte[]{65,66}));
        check("close-empty-reason", cat(new byte[]{0x1d}, vi(1), vi(0)));
        check("datagram-plain", cat(new byte[]{0x30}, new byte[]{4,5,6}));
        check("datagram-len", cat(new byte[]{0x31}, vi(2), new byte[]{4,5}));
        System.out.println("ALL CODEC ROUND-TRIPS PASSED");
    }
}
